diff:
--- adapted_patch
+++ downstream_patch
@@ -1,36 +1,71 @@
-From d0bd262ea76714cfa82509809094051dd0542993 Mon Sep 17 00:00:00 2001
-From: root <root@congroo>
-Date: Thu, 9 Jan 2025 17:11:34 +0800
-Subject: [PATCH] Adapted patch for linux-6.12.y
+From f5c5661f02b5539d88aea8497f8d0835d165e945 Mon Sep 17 00:00:00 2001
+From: Chris Lu <chris.lu@mediatek.com>
+Date: Mon, 23 Sep 2024 16:47:05 +0800
+Subject: [PATCH] Bluetooth: btusb: mediatek: change the conditions for ISO
+ interface

+commit defc33b5541e0a7e45cc2d99d72fbe80a597afc5 upstream.
+
+Change conditions for Bluetooth driver claiming and releasing usb
+ISO interface for MediaTek ISO data transmission.
+
+Signed-off-by: Chris Lu <chris.lu@mediatek.com>
+Signed-off-by: Luiz Augusto von Dentz <luiz.von.dentz@intel.com>
+Cc: Fedor Pchelkin <boddah8794@gmail.com>
+Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>
 ---
- drivers/bluetooth/btusb.c | 6 +++---
- 1 file changed, 3 insertions(+), 3 deletions(-)
+ drivers/bluetooth/btusb.c | 16 ++++++++--------
+ 1 file changed, 8 insertions(+), 8 deletions(-)

 diff --git a/drivers/bluetooth/btusb.c b/drivers/bluetooth/btusb.c
-index 11755cb1eb16..3354861e9fd4 100644
+index d7515dc0e77e4..0c85c981a8334 100644
 --- a/drivers/bluetooth/btusb.c
 +++ b/drivers/bluetooth/btusb.c
-@@ -2647,7 +2647,7 @@ static void btusb_mtk_release_iso_intf(struct btusb_data *data)
+@@ -2648,7 +2648,7 @@ static void btusb_mtk_release_iso_intf(struct hci_dev *hdev)
  {
- 	struct btmtk_data *btmtk_data = hci_get_priv(data->hdev);
+ 	struct btmtk_data *btmtk_data = hci_get_priv(hdev);

 -	if (btmtk_data->isopkt_intf) {
 +	if (test_bit(BTMTK_ISOPKT_OVER_INTR, &btmtk_data->flags)) {
  		usb_kill_anchored_urbs(&btmtk_data->isopkt_anchor);
  		clear_bit(BTMTK_ISOPKT_RUNNING, &btmtk_data->flags);

-@@ -2677,8 +2677,8 @@ static int btusb_mtk_reset(struct hci_dev *hdev, void *rst_data)
+@@ -2688,8 +2688,8 @@ static int btusb_mtk_reset(struct hci_dev *hdev, void *rst_data)
  	if (err < 0)
  		return err;

 -	if (test_bit(BTMTK_ISOPKT_RUNNING, &btmtk_data->flags))
--		btusb_mtk_release_iso_intf(data);
+-		btusb_mtk_release_iso_intf(hdev);
 +	/* Release MediaTek ISO data interface */
 +	btusb_mtk_release_iso_intf(hdev);

  	btusb_stop_traffic(data);
  	usb_kill_anchored_urbs(&data->tx_anchor);
--- 
-2.25.1
-
+@@ -2734,22 +2734,22 @@ static int btusb_mtk_setup(struct hci_dev *hdev)
+ 	btmtk_data->reset_sync = btusb_mtk_reset;
+ 
+ 	/* Claim ISO data interface and endpoint */
+-	btmtk_data->isopkt_intf = usb_ifnum_to_if(data->udev, MTK_ISO_IFNUM);
+-	if (btmtk_data->isopkt_intf)
++	if (!test_bit(BTMTK_ISOPKT_OVER_INTR, &btmtk_data->flags)) {
++		btmtk_data->isopkt_intf = usb_ifnum_to_if(data->udev, MTK_ISO_IFNUM);
+ 		btusb_mtk_claim_iso_intf(data);
++	}
+ 
+ 	return btmtk_usb_setup(hdev);
+ }
+ 
+ static int btusb_mtk_shutdown(struct hci_dev *hdev)
+ {
+-	struct btmtk_data *btmtk_data = hci_get_priv(hdev);
+ 	int ret;
+ 
+ 	ret = btmtk_usb_shutdown(hdev);
+ 
+-	if (test_bit(BTMTK_ISOPKT_RUNNING, &btmtk_data->flags))
+-		btusb_mtk_release_iso_intf(hdev);
++	/* Release MediaTek iso interface after shutdown */
++	btusb_mtk_release_iso_intf(hdev);
+ 
+ 	return ret;
+ }

--- adapted_patch
+++ downstream_patch
@@ -1,17 +1,29 @@
-From 131d2e8462f9711931611c0f6ddaef665de07fa1 Mon Sep 17 00:00:00 2001
-From: root <root@congroo>
-Date: Thu, 9 Jan 2025 17:12:12 +0800
-Subject: [PATCH] Adapted patch for linux-6.12.y
+From cc569d791ab2a0de74f76e470515d25d24c9b84b Mon Sep 17 00:00:00 2001
+From: Chris Lu <chris.lu@mediatek.com>
+Date: Mon, 23 Sep 2024 16:47:04 +0800
+Subject: [PATCH] Bluetooth: btusb: mediatek: add intf release flow when usb
+ disconnect

+commit 489304e67087abddc2666c5af0159cb95afdcf59 upstream.
+
+MediaTek claim an special usb intr interface for ISO data transmission.
+The interface need to be released before unregistering hci device when
+usb disconnect. Removing BT usb dongle without properly releasing the
+interface may cause Kernel panic while unregister hci device.
+
+Signed-off-by: Chris Lu <chris.lu@mediatek.com>
+Signed-off-by: Luiz Augusto von Dentz <luiz.von.dentz@intel.com>
+Cc: Fedor Pchelkin <boddah8794@gmail.com>
+Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>
 ---
- drivers/bluetooth/btusb.c | 17 ++++++++++++++---
- 1 file changed, 14 insertions(+), 3 deletions(-)
+ drivers/bluetooth/btusb.c | 20 +++++++++++++++-----
+ 1 file changed, 15 insertions(+), 5 deletions(-)

 diff --git a/drivers/bluetooth/btusb.c b/drivers/bluetooth/btusb.c
-index 11755cb1eb16..27e61574fbcd 100644
+index 5f7cfee014397..d7515dc0e77e4 100644
 --- a/drivers/bluetooth/btusb.c
 +++ b/drivers/bluetooth/btusb.c
-@@ -2643,9 +2643,9 @@ static void btusb_mtk_claim_iso_intf(struct btusb_data *data)
+@@ -2644,9 +2644,9 @@ static void btusb_mtk_claim_iso_intf(struct btusb_data *data)
  	init_usb_anchor(&btmtk_data->isopkt_anchor);
  }

@@ -23,7 +35,7 @@

  	if (btmtk_data->isopkt_intf) {
  		usb_kill_anchored_urbs(&btmtk_data->isopkt_anchor);
-@@ -2661,6 +2661,16 @@ static void btusb_mtk_release_iso_intf(struct btusb_data *data)
+@@ -2662,6 +2662,16 @@ static void btusb_mtk_release_iso_intf(struct btusb_data *data)
  	clear_bit(BTMTK_ISOPKT_OVER_INTR, &btmtk_data->flags);
  }

@@ -40,7 +52,7 @@
  static int btusb_mtk_reset(struct hci_dev *hdev, void *rst_data)
  {
  	struct btusb_data *data = hci_get_drvdata(hdev);
-@@ -2678,7 +2688,7 @@ static int btusb_mtk_reset(struct hci_dev *hdev, void *rst_data)
+@@ -2679,7 +2689,7 @@ static int btusb_mtk_reset(struct hci_dev *hdev, void *rst_data)
  		return err;

  	if (test_bit(BTMTK_ISOPKT_RUNNING, &btmtk_data->flags))
@@ -49,7 +61,23 @@

  	btusb_stop_traffic(data);
  	usb_kill_anchored_urbs(&data->tx_anchor);
-@@ -3850,6 +3860,7 @@ static int btusb_probe(struct usb_interface *intf,
+@@ -2733,14 +2743,13 @@ static int btusb_mtk_setup(struct hci_dev *hdev)
+ 
+ static int btusb_mtk_shutdown(struct hci_dev *hdev)
+ {
+-	struct btusb_data *data = hci_get_drvdata(hdev);
+ 	struct btmtk_data *btmtk_data = hci_get_priv(hdev);
+ 	int ret;
+ 
+ 	ret = btmtk_usb_shutdown(hdev);
+ 
+ 	if (test_bit(BTMTK_ISOPKT_RUNNING, &btmtk_data->flags))
+-		btusb_mtk_release_iso_intf(data);
++		btusb_mtk_release_iso_intf(hdev);
+ 
+ 	return ret;
+ }
+@@ -3854,6 +3863,7 @@ static int btusb_probe(struct usb_interface *intf,
  		data->recv_acl = btmtk_usb_recv_acl;
  		data->suspend = btmtk_usb_suspend;
  		data->resume = btmtk_usb_resume;
@@ -57,6 +85,3 @@
  	}

  	if (id->driver_info & BTUSB_SWAVE) {
--- 
-2.25.1
-
